def sortColors(nums):
    p0, i, p2 = 0, 0, len(nums) - 1
    while i <= p2:
        if nums[i] == 0:
            nums[i], nums[p0] = nums[p0], nums[i]  # 归入 0 区
            p0 += 1; i += 1
        elif nums[i] == 2:
            nums[i], nums[p2] = nums[p2], nums[i]  # 归入 2 区
            p2 -= 1  # 换来的数未检查，i 不动
        else:
            i += 1  # 数字 1 留在中间

def nextPermutation(nums):
    n = len(nums)
    i = n - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1  # 从右找第一个升序对的左端
    if i >= 0:
        j = n - 1
        while nums[j] <= nums[i]:
            j -= 1  # 找到刚大于 nums[i] 的数
        nums[i], nums[j] = nums[j], nums[i]
    l, r = i + 1, n - 1
    while l < r:
        nums[l], nums[r] = nums[r], nums[l]  # 后缀原地反转成最小
        l, r = l + 1, r - 1

