def firstMissingPositive(nums):
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            j = nums[i] - 1
            nums[i], nums[j] = nums[j], nums[i]  # 值 v 归位到下标 v-1
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1  # 首个错位处即答案
    return n + 1

def rotate(matrix):
    n = len(matrix)
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]  # 转置
    for row in matrix:
        row.reverse()  # 每行左右翻转

def majorityElement(nums):
    cand, cnt = None, 0
    for x in nums:
        if cnt == 0:
            cand = x  # 计数耗尽，换候选
        cnt += 1 if x == cand else -1  # 同加异减，两两抵消
    return cand

def findDuplicate(nums):
    slow = fast = 0
    while True:
        slow = nums[slow]  # 慢指针走一步
        fast = nums[nums[fast]]  # 快指针走两步
        if slow == fast:
            break  # 相遇，确认有环
    slow = 0  # 回到起点
    while slow != fast:
        slow = nums[slow]
        fast = nums[fast]  # 同速前进
    return slow  # 环入口即重复数

def sortArray(nums):
    if len(nums) <= 1:
        return nums
    mid = len(nums) // 2
    left = sortArray(nums[:mid])  # 递归排序左半
    right = sortArray(nums[mid:])  # 递归排序右半
    res, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            res.append(left[i])  # 取较小者
            i += 1
        else:
            res.append(right[j])
            j += 1
    return res + left[i:] + right[j:]  # 拼接剩余尾部
